CREATE TABLE wl_categories(id TEXT PRIMARY KEY, parent_id TEXT REFERENCES wl_categories(id), CHECK(id<>parent_id));
CREATE TABLE wl_templates(id TEXT PRIMARY KEY, revision INTEGER NOT NULL CHECK(revision>0), category TEXT NOT NULL REFERENCES wl_categories(id), name_key TEXT NOT NULL, search_text TEXT NOT NULL, retired INTEGER NOT NULL DEFAULT 0 CHECK(retired IN (0,1)), UNIQUE(category,name_key));
CREATE TABLE wl_versions(id TEXT NOT NULL REFERENCES wl_templates(id), revision INTEGER NOT NULL CHECK(revision>0), digest TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(id,revision));
CREATE TABLE wl_links(id TEXT NOT NULL, revision INTEGER NOT NULL, ordinal INTEGER NOT NULL, relation TEXT NOT NULL CHECK(relation IN ('component','input','output','spell','combines','species','starting_inventory')), target_id TEXT NOT NULL, target_revision INTEGER NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>0), role TEXT NOT NULL, PRIMARY KEY(id,revision,ordinal), FOREIGN KEY(id,revision) REFERENCES wl_versions(id,revision), FOREIGN KEY(target_id,target_revision) REFERENCES wl_versions(id,revision));
CREATE TABLE wl_proposals(id TEXT PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('pending','approved','rejected')), payload TEXT NOT NULL);
CREATE TABLE wl_audit(sequence INTEGER PRIMARY KEY GENERATED_BY_BACKEND, actor TEXT NOT NULL, action TEXT NOT NULL, subject TEXT NOT NULL, payload TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE wl_worlds(id TEXT PRIMARY KEY, engine_version TEXT NOT NULL, revision INTEGER NOT NULL CHECK(revision>=0), source_digest TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE wl_instances(world_id TEXT NOT NULL REFERENCES wl_worlds(id), id TEXT NOT NULL, template_id TEXT NOT NULL, template_revision INTEGER NOT NULL, owner_id TEXT, parent_id TEXT, quantity INTEGER NOT NULL CHECK(quantity>=0), payload TEXT NOT NULL, PRIMARY KEY(world_id,id), FOREIGN KEY(template_id,template_revision) REFERENCES wl_versions(id,revision), FOREIGN KEY(world_id,owner_id) REFERENCES wl_instances(world_id,id) DEFERRABLE INITIALLY DEFERRED, FOREIGN KEY(world_id,parent_id) REFERENCES wl_instances(world_id,id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE wl_relationships(world_id TEXT NOT NULL, actor_id TEXT NOT NULL, target_id TEXT NOT NULL, trust INTEGER NOT NULL CHECK(trust BETWEEN -10 AND 10), payload TEXT NOT NULL, PRIMARY KEY(world_id,actor_id,target_id), FOREIGN KEY(world_id,actor_id) REFERENCES wl_instances(world_id,id), FOREIGN KEY(world_id,target_id) REFERENCES wl_instances(world_id,id));
CREATE TABLE wl_schemas(id TEXT PRIMARY KEY, schema_json TEXT NOT NULL);
CREATE TABLE wl_legacy_definitions(world_id TEXT NOT NULL REFERENCES wl_worlds(id), id TEXT NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(world_id,id));
CREATE TABLE wl_legacy_instances(world_id TEXT NOT NULL REFERENCES wl_worlds(id), id TEXT NOT NULL, definition_id TEXT NOT NULL, quantity INTEGER NOT NULL CHECK(quantity>=0), payload TEXT NOT NULL, PRIMARY KEY(world_id,id), FOREIGN KEY(world_id,definition_id) REFERENCES wl_legacy_definitions(world_id,id));
CREATE INDEX wl_legacy_type ON wl_legacy_instances(world_id,definition_id);
CREATE INDEX wl_category_search ON wl_templates(category,retired);
CREATE INDEX wl_component_target ON wl_links(target_id,target_revision);
CREATE INDEX wl_owner ON wl_instances(world_id,owner_id);
CREATE INDEX wl_parent ON wl_instances(world_id,parent_id);
CREATE INDEX wl_template_instances ON wl_instances(template_id,template_revision);
CREATE INDEX wl_audit_subject ON wl_audit(subject,sequence);
